    'MAR': 3, 'MARCH': 3,
    'APR': 4, 'APRIL': 4,
    'MAY': 5,
    'JUN': 6, 'JUNE': 6,
    'JUL': 7, 'JULY': 7,
    'AUG': 8, 'AUGUST': 8,
    'SEP': 9, 'SEPT': 9, 'SEPTEMBER': 9,
    'OCT': 10, 'OCTOBER': 10,
    'NOV': 11, 'NOVEMBER': 11,
    'DEC': 12, 'DECEMBER': 12,
}

DATE_PATTERNS = [
    # YYYY-MM-DD / YYYY/MM/DD / YYYY.MM.DD
    re.compile(r'(20\d{2})[./-](\d{1,2})[./-](\d{1,2})'),
    # DD-MM-YYYY or DD/MM/YY (assume day/month)
    re.compile(r'(\d{1,2})[./-](\d{1,2})[./-](20\d{2}|\d{2})'),
    # DD Mon YYYY
    re.compile(r'(\d{1,2})\s*([A-Za-z]{3,9})\s*(20\d{2}|\d{2})'),
    # Mon DD YYYY
    re.compile(r'([A-Za-z]{3,9})\s*(\d{1,2})[,]?\s*(20\d{2}|\d{2})'),
]

NUM_RE = re.compile(r'(\d{1,3}(?:,\d{3})*(?:\.\d{1,2})?|\d+\.\d{1,2})')


def normalize_year(y: str) -> int:
    if len(y) == 2:
        return 2000 + int(y)
    return int(y)


