    candidates = []
    for pattern in DATE_PATTERNS:
        for m in pattern.finditer(text):
            try:
                if pattern is DATE_PATTERNS[0]:
                    year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif pattern is DATE_PATTERNS[1]:
                    day, month, year = int(m.group(1)), int(m.group(2)), normalize_year(m.group(3))
                elif pattern is DATE_PATTERNS[2]:
                    day = int(m.group(1))
                    month_str = m.group(2).upper()
                    month = MONTHS.get(month_str[:3], MONTHS.get(month_str, 0))
                    year = normalize_year(m.group(3))
                else:
                    month_str = m.group(1).upper()
                    month = MONTHS.get(month_str[:3], MONTHS.get(month_str, 0))
                    day = int(m.group(2))
                    year = normalize_year(m.group(3))
                if not (1 <= month <= 12 and 1 <= day <= 31):
                    continue
                dt = datetime(year, month, day)
                candidates.append((m.start(), dt))
            except Exception:
                continue
    if not candidates:
        return None
    candidates.sort(key=lambda x: x[0])
    return candidates[0][1].strftime('%Y-%m-%d')


def extract_amount_from_line(line: str):
    matches = NUM_RE.findall(line)
    if not matches:
        return None
    raw = matches[-1]
    raw = raw.replace(',', '')
    try:
        val = Decimal(raw)
    except InvalidOperation:
        return None
    return f"{val:.2f}"


def extract_total_amount(text: str):
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    # Iterate by keyword priority
    for group in KEYWORD_GROUPS:
        for idx, line in enumerate(lines):
            upper = line.upper()
            if any(ex in upper for ex in EXCLUSION_KEYWORDS):
                continue
            if any(k in upper for k in group):
                amt = extract_amount_from_line(line)
                if amt:
                    return amt
                # fallback: next line
                if idx + 1 < len(lines):
                    amt = extract_amount_from_line(lines[idx + 1])
                    if amt:
                        return amt
    return None


def ocr_image(path: str) -> str:
    img = Image.open(path)
    # Basic preprocessing to improve OCR
    img = img.convert('L')
    img = ImageOps.autocontrast(img)
    img = img.filter(ImageFilter.MedianFilter(size=3))
    # Binarize
    img = img.point(lambda x: 0 if x < 140 else 255, '1')
    return pytesseract.image_to_string(img, config='--psm 6')


def main():
    files = [f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png', '.tif', '.tiff', '.bmp'))]
    files.sort()

    rows = []
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        try:
            text = ocr_image(path)
        except Exception:
            text = ''
        date_val = parse_date(text) if text else None
        total_val = extract_total_amount(text) if text else None
        rows.append((fname, date_val, total_val))

    wb = Workbook()
    # Remove default sheet
    default = wb.active
    wb.remove(default)
    ws = wb.create_sheet(title='results')
    ws.append(['filename', 'date', 'total_amount'])
    for r in rows:
        ws.append(list(r))

    wb.save(OUT_PATH)


if __name__ == '__main__':
    main()
