import os, re
from decimal import Decimal, InvalidOperation
from datetime import datetime
from PIL import Image, ImageOps
import pytesseract
from openpyxl import Workbook

IMG_DIR = '/app/workspace/dataset/img'
OUT_PATH = '/app/workspace/stat_ocr.xlsx'

KEYWORD_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]
EXCLUSION_KEYWORDS = [
    'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED',
    'QTY', 'ITEM', 'ITEMS', 'INCLUDES', 'INCL'
]

MONTHS = {
    'JAN': 1, 'JANUARY': 1,
    'FEB': 2, 'FEBRUARY': 2,
    'MAR': 3, 'MARCH': 3,
    'APR': 4, 'APRIL': 4,
    'MAY': 5,
    'JUN': 6, 'JUNE': 6,
    'JUL': 7, 'JULY': 7,
    'AUG': 8, 'AUGUST': 8,
    'SEP': 9, 'SEPT': 9, 'SEPTEMBER': 9,
    'OCT': 10, 'OCTOBER': 10,
    'NOV': 11, 'NOVEMBER': 11,
    'DEC': 12, 'DECEMBER': 12,
}

DATE_PATTERNS = [
    re.compile(r'(20\d{2})[./-](\d{1,2})[./-](\d{1,2})'),
    re.compile(r'(\d{1,2})[./-](\d{1,2})[./-](20\d{2}|\d{2})'),
    re.compile(r'(\d{1,2})\s*([A-Za-z]{3,9})\s*(20\d{2}|\d{2})'),
    re.compile(r'([A-Za-z]{3,9})\s*(\d{1,2})[,]?\s*(20\d{2}|\d{2})'),
]

DECIMAL_RE = re.compile(r'\d+\.\d{2}')
SPLIT_DECIMAL_RE = re.compile(r'(\d{1,6})\s+(\d{2})(?!\d)')
INT_RE = re.compile(r'\d{1,6}')


def normalize_year(y: str) -> int:
    if len(y) == 2:
        return 2000 + int(y)
    return int(y)


def extract_dates(text: str):
    candidates = []
    for pattern in DATE_PATTERNS:
        for m in pattern.finditer(text):
            try:
                if pattern is DATE_PATTERNS[0]:
                    year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif pattern is DATE_PATTERNS[1]:
                    day, month, year = int(m.group(1)), int(m.group(2)), normalize_year(m.group(3))
                elif pattern is DATE_PATTERNS[2]:
                    day = int(m.group(1))
                    month_str = m.group(2).upper()
                    month = MONTHS.get(month_str[:3], MONTHS.get(month_str, 0))
                    year = normalize_year(m.group(3))
                else:
                    month_str = m.group(1).upper()
                    month = MONTHS.get(month_str[:3], MONTHS.get(month_str, 0))
                    day = int(m.group(2))
                    year = normalize_year(m.group(3))
                if not (1 <= month <= 12 and 1 <= day <= 31):
                    continue
                if not (1990 <= year <= 2030):
                    continue
                dt = datetime(year, month, day)
                candidates.append((m.start(), dt.strftime('%Y-%m-%d')))
            except Exception:
                continue
    return candidates


def choose_best_date(texts):
    counts = {}
    min_pos = {}
    for txt in texts:
        for pos, d in extract_dates(txt):
            counts[d] = counts.get(d, 0) + 1
            if d not in min_pos or pos < min_pos[d]:
                min_pos[d] = pos
    if not counts:
        return None
    best = sorted(counts.items(), key=lambda kv: (-kv[1], min_pos.get(kv[0], 1e9), kv[0]))
    return best[0][0]


def extract_amount_from_line(line: str):
    cleaned = line.replace(',', '')
    decs = DECIMAL_RE.findall(cleaned)
    if decs:
        try:
            return f"{Decimal(decs[-1]):.2f}"
        except InvalidOperation:
            pass
    split = SPLIT_DECIMAL_RE.findall(cleaned)
    if split:
        whole, frac = split[-1]
        try:
            return f"{Decimal(f'{whole}.{frac}'):.2f}"
        except InvalidOperation:
            pass
    ints = INT_RE.findall(cleaned)
    if ints:
        try:
            return f"{Decimal(ints[-1]):.2f}"
        except InvalidOperation:
            return None
    return None


def line_has_keyword(line_upper: str, keyword: str) -> bool:
    if keyword in line_upper:
        return True
    if ' ' in keyword:
        parts = keyword.split()
        return all(p in line_upper for p in parts)
    return False


def extract_total_amount(text: str):
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    for group in KEYWORD_GROUPS:
        for idx, line in enumerate(lines):
            upper = line.upper()
            if any(ex in upper for ex in EXCLUSION_KEYWORDS):
                continue
            if any(line_has_keyword(upper, k) for k in group):
                amt = extract_amount_from_line(line)
                if amt:
                    return amt
                if idx + 1 < len(lines):
                    amt = extract_amount_from_line(lines[idx + 1])
                    if amt:
                        return amt
    return None


def ocr_texts(path: str):
    img = Image.open(path)
    gray_auto = ImageOps.autocontrast(img.convert('L'))
    texts = []
    for im in (img, gray_auto):
        for psm in (6, 4):
            try:
                txt = pytesseract.image_to_string(im, config=f'--psm {psm}')
                if txt:
                    texts.append(txt)
            except Exception:
                continue
    return texts


def ocr_extra(path: str):
    img = Image.open(path)
    gray = ImageOps.autocontrast(img.convert('L'))
    bin_img = gray.point(lambda x: 0 if x < 140 else 255, '1')
    texts = []
    try:
        txt = pytesseract.image_to_string(bin_img, config='--psm 6')
        if txt:
            texts.append(txt)
    except Exception:
        pass
    return texts


def extract_from_texts(texts):
    date_val = choose_best_date(texts) if texts else None
    total_val = None
    if texts:
        for txt in texts:
            if total_val is None:
                total_val = extract_total_amount(txt)
            if total_val:
                break
    return date_val, total_val


def main():
    files = [f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png', '.tif', '.tiff', '.bmp'))]
    files.sort()

    rows = []
    for fname in files:
        path = os.path.join(IMG_DIR, fname)
        texts = ocr_texts(path)
        date_val, total_val = extract_from_texts(texts) if texts else (None, None)
        if date_val is None or total_val is None:
            extra_texts = ocr_extra(path)
            if extra_texts:
                extra_date, extra_total = extract_from_texts(extra_texts)
                if date_val is None:
                    date_val = extra_date
                if total_val is None:
                    total_val = extra_total
        rows.append((fname, date_val, total_val))

    wb = Workbook()
    default = wb.active
    wb.remove(default)
    ws = wb.create_sheet(title='results')
    ws.append(['filename', 'date', 'total_amount'])
    for r in rows:
        ws.append(list(r))

    wb.save(OUT_PATH)


if __name__ == '__main__':
    main()
